int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    int error;
    struct sk_buff *skb;
    size_t copied = 0;

    if (sock->type == SOCK_STREAM && (flags & MSG_OOB)) {
        return -EOPNOTSUPP;
    }

    skb = skb_recv_datagram(sock->sk, flags, NULL, &error);
    if (!skb) {
        return error;
    }

    copied = skb->len;
    if (len < copied) {
        msg->msg_flags |= MSG_TRUNC;
        copied = len;
    }

    error = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, copied);
    if (error) {
        return error;
    }

    skb_free_datagram(sock->sk, skb);
    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (sock->sk->sk_state == TCP_LISTEN) {
        return -EINVAL;
    }

    skb = skb_recv_datagram(sock->sk, flags, &err);
    if (!skb) {
        return err;
    }

    if (flags & MSG_TRUNC) {
        copied = skb->len;
    } else {
        copied = min(len, (size_t)skb->len);
    }

    err = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (err) {
        return err;
    }

    if (sock->sk->sk_type == SOCK_DGRAM && (flags & MSG_TRUNC) && copied < skb->len) {
        msg->msg_flags |= MSG_TRUNC;
    }

    if (flags & MSG_OOB) {
        sock->sk->sk_urg_data = 0;
    }

    sock_update_backlog(sock);

    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int error;
    int data_len;

    if (sk->sk_state == TCP_LISTEN)
        return -ENOTCONN;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    if (sk->sk_type == SOCK_DGRAM) {
        data_len = skb_recv_datagram(sk, flags, &error);
        if (data_len < 0)
            return data_len;

        if (copy_to_iter(skb->data, data_len, msg->msg_iter) != data_len)
            return -EFAULT;
    } else if (sk->sk_type == SOCK_STREAM) {
        data_len = 0;
        while (len > 0 && (error = sock_recvmsg_one(sk, msg, len, flags)) > 0) {
            data_len += error;
            len -= error;
        }
        if (error < 0)
            return error;
    }

    return data_len;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    lock_sock(sk);
    ret = sk->sk_prot->recvmsg(iocb, sk, msg, len, flags, NULL);
    release_sock(sk);

    return ret;
}

#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/slab.h>
#include <linux/net.h>

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    ret = sock->ops->recvmsg(iocb, sock, msg, len, flags);

    if (ret > 0)
        msg->msg_namelen = 0;

    return ret;
}
